window.NARRATION = {"ci_a": {"dur": 22.72, "text": "Pressure shows how you actually lead. This is where you start to see the gap between instinct and intention. Take about 30 seconds on each of these. Write what actually went on inside you, rather than what you think should have happened. Only you can see what you write, and it's saved here so you can come back to it. Select Save on each one as you go, then select Next.", "sents": [[0.03, "Pressure shows how you actually lead.", 0], [2.93, "This is where you start to see the gap between instinct and intention.", 0], [7.35, "Take about 30 seconds on each of these.", 1], [9.97, "Write what actually went on inside you, rather than what you think should have happened.", 1], [14.69, "Only you can see what you write, and it's saved here so you can come back to it.", 1], [19.05, "Select Save on each one as you go, then select Next.", 2]], "v": "k1", "cues": [0.03, 7.35, 19.05]}, "ci_b": {"dur": 10.8, "text": "Now look at what you wrote and pick the pattern that's closest to it. There's no right answer. Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", "sents": [[0.01, "Now look at what you wrote and pick the pattern that's closest to it.", 0], [3.75, "There's no right answer.", 1], [5.23, "Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", 1]], "v": "k1", "cues": [0.01, 3.75]}, "ci_c": {"dur": 20.08, "text": "Now run the Foundation Reset. Say your five words, the ones you saved on the Foundation Reset screen. Ask yourself for two next-best steps. Pick the one you'll take in the next ten minutes. Then take one breath and answer the anchor on the last card. It takes about a minute and works best standing up, so do it now before you move on.", "sents": [[0, "Now run the Foundation Reset.", 0], [2.15, "Say your five words, the ones you saved on the Foundation Reset screen.", 1], [6.37, "Ask yourself for two next-best steps.", 1], [9.07, "Pick the one you'll take in the next ten minutes.", 1], [11.71, "Then take one breath and answer the anchor on the last card.", 1], [15.41, "It takes about a minute and works best standing up, so do it now before you move on.", 2]], "v": "k1", "cues": [0, 2.15, 15.41]}, "kc_retry": {"dur": 3.68, "text": "Not quite. Have another look, then try again.", "sents": [[0.05, "Not quite.", 0], [1.45, "Have another look, then try again.", 0]], "v": "v4l", "cues": [0.05]}, "n_4_0": {"dur": 12.24, "text": "Lesson 4 puts your M.V.P. to work as a filter for decisions and as your answer when you meet resistance. It takes about 40 minutes here, then one core rep this week. Select Start Lesson.", "sents": [[0, "Lesson 4 puts your M.V.P. to work as a filter for decisions and as your answer when you meet resistance.", 0], [7.07, "It takes about 40 minutes here, then one core rep this week.", 1], [10.81, "Select Start Lesson.", 1]], "v": "k1", "cues": [0, 7.07]}, "n_4_1": {"dur": 11.36, "text": "Read this moment. What would you say in the next five seconds? That answer is where resilience shows up. This lesson gives you two moves for that moment and one for the week before it.", "sents": [[0.01, "Read this moment.", 0], [1.71, "What would you say in the next five seconds?", 0], [4.19, "That answer is where resilience shows up.", 1], [6.93, "This lesson gives you two moves for that moment and one for the week before it.", 1]], "v": "v4l", "cues": [0.01, 4.19]}, "n_4_10": {"dur": 25.92, "text": "Resistance comes from two places, and each one needs a different move. Internal resistance is your inner critic. Name the exact sentence it says and answer it once in writing, drawing on your purpose. External resistance comes from other people or limited resources. Treat their “no” as “not yet,” and ask what the last attempt taught you. Sort these into internal and external.", "sents": [[0.05, "Resistance comes from two places, and each one needs a different move.", 0], [5.17, "Internal resistance is your inner critic.", 1], [7.91, "Name the exact sentence it says and answer it once in writing, drawing on your purpose.", 1], [13.97, "External resistance comes from other people or limited resources.", 1], [18.23, "Treat their “no” as “not yet,” and ask what the last attempt taught you.", 1], [23.37, "Sort these into internal and external.", 2]], "v": "k1", "cues": [0.05, 5.17, 23.37]}, "n_4_12": {"dur": 6.32, "text": "Back to the room, where everyone is looking at you. Choose what you'd say, and you'll hear where it leads.", "sents": [[0, "Back to the room, where everyone is looking at you.", 0], [3.49, "Choose what you'd say, and you'll hear where it leads.", 1]], "v": "v4l", "cues": [0, 3.49]}, "n_4_12_o0": {"dur": 10.48, "text": "That's polite, but it's a missed chance. You've accepted the no as a verdict, and you've learned nothing about why the last attempt failed. Try the other option to compare.", "sents": [[0.05, "That's polite, but it's a missed chance.", 0], [3.35, "You've accepted the no as a verdict, and you've learned nothing about why the last attempt failed.", 0], [8.73, "Try the other option to compare.", 0]], "v": "k1", "cues": [0.05]}, "n_4_12_o1": {"dur": 8.0, "text": "That's the reframe. You've turned a shutdown into a question that gathers data, and you've made the skeptic part of the solution.", "sents": [[0, "That's the reframe.", 0], [1.77, "You've turned a shutdown into a question that gathers data, and you've made the skeptic part of the solution.", 0]], "v": "r3", "cues": [0]}, "n_4_14": {"dur": 10.8, "text": "Time for the drill. This one is about how quickly you recover when something goes wrong. Press Play. The video pauses a few times so you can answer, and it resumes when you're done.", "sents": [[0.01, "Time for the drill.", 0], [1.47, "This one is about how quickly you recover when something goes wrong.", 0], [5.55, "Press Play.", 1], [6.65, "The video pauses a few times so you can answer, and it resumes when you're done.", 1]], "v": "k1", "cues": [0.01, 5.55]}, "n_4_15": {"dur": 37.76, "text": "Your core rep this week is the decision filter. It takes about fifteen minutes. Work the four questions using the scenario, then do the same with one real request from your week. If you have more time, write down the exact sentence your inner critic says and your answer to it. Then take one real no from the last month and reframe it as “not yet,” and write the question you'll ask. Take one goal you're working toward, find where it's most likely to break, and write the pivot. Run your core rep, then ask one person for feedback on how you applied the decision filter. Select Open your Lesson 4 pages to begin.", "sents": [[0.01, "Your core rep this week is the decision filter.", 0], [2.93, "It takes about fifteen minutes.", 0], [4.95, "Work the four questions using the scenario, then do the same with one real request from your week.", 0], [10.93, "If you have more time, write down the exact sentence your inner critic says and your answer to it.", 1], [16.85, "Then take one real no from the last month and reframe it as “not yet,” and write the question you'll ask.", 1], [23.95, "Take one goal you're working toward, find where it's most likely to break, and write the pivot.", 2], [29.53, "Run your core rep, then ask one person for feedback on how you applied the decision filter.", 3], [34.79, "Select Open your Lesson 4 pages to begin.", 3]], "v": "k1", "cues": [0.01, 10.93, 23.95, 29.53]}, "n_4_16": {"dur": 10.32, "text": "This lesson's Athleader Pro is Sagar Pandya, the AI Integrator. He helps leaders keep people and technology pulling in the same direction. Press play to hear from him.", "sents": [[0, "This lesson's Athleader Pro is Sagar Pandya, the AI Integrator.", 0], [4.81, "He helps leaders keep people and technology pulling in the same direction.", 0], [9.09, "Press play to hear from him.", 1]], "v": "r3", "cues": [0, 9.09]}, "n_4_17": {"dur": 15.6, "text": "Sagar's drill is a fifteen-minute exercise to run with your team to get everyone aligned on one mission. Save it for your next team meeting or select Start the timer to see how it runs. When you've completed the drill or scheduled a time to run it, select the option that fits.", "sents": [[0, "Sagar's drill is a fifteen-minute exercise to run with your team to get everyone aligned on one mission.", 0], [6.55, "Save it for your next team meeting or select Start the timer to see how it runs.", 1], [11.13, "When you've completed the drill or scheduled a time to run it, select the option that fits.", 1]], "v": "k1", "cues": [0, 6.55]}, "n_4_19_q0": {"dur": 6.4, "text": "A few questions to check the main ideas. In the decision filter, when do you stop asking questions?", "sents": [[0, "A few questions to check the main ideas.", 0], [2.73, "In the decision filter, when do you stop asking questions?", 0]], "v": "r3", "cues": [0]}, "n_4_19_q1": {"dur": 5.12, "text": "Your inner critic says, “You're not ready for this.” What's the conditioned response?", "sents": [[0.05, "Your inner critic says, “You're not ready for this.”", 0], [3.53, "What's the conditioned response?", 0]], "v": "v4l", "cues": [0.05]}, "n_4_19_q2": {"dur": 8.08, "text": "Last one. Your 90-day goal depends on one supplier delivering in week 6. What does stress-testing that goal mean?", "sents": [[0, "Last one.", 0], [1.21, "Your 90-day goal depends on one supplier delivering in week 6.", 0], [5.89, "What does stress-testing that goal mean?", 0]], "v": "k1", "cues": [0]}, "n_4_19_w0": {"dur": 7.12, "text": "Stop at the first no. Then look for the better yes: Who else could grow and what you could offer instead.", "sents": [[0.03, "Stop at the first no.", 0], [1.97, "Then look for the better yes: Who else could grow and what you could offer instead.", 0]], "v": "v4l", "cues": [0.03]}, "n_4_19_w1": {"dur": 8.32, "text": "Name the exact sentence and answer it once in writing, drawing on your purpose. You don't argue with it, and you don't obey it.", "sents": [[0, "Name the exact sentence and answer it once in writing, drawing on your purpose.", 0], [5.45, "You don't argue with it, and you don't obey it.", 0]], "v": "k1", "cues": [0]}, "n_4_19_w2": {"dur": 6.24, "text": "Agility is planned ahead. You find the weak link now and decide the pivot while you're calm.", "sents": [[0.05, "Agility is planned ahead.", 0], [2.33, "You find the weak link now and decide the pivot while you're calm.", 0]], "v": "v4l", "cues": [0.05]}, "n_4_20": {"dur": 35.2, "text": "Before you go, a quick recap. The filter gives you a reason for saying yes or no. Check purpose, mission, and values, then look for the better yes. Resistance comes in two kinds. Name your inner critic and answer it once. Treat an outside “no” as “not yet” and ask a question. And agility is planned before it's needed. Find the weak link in a goal now, and decide on a pivot while you're calm. Select Download my answers for a Word document of what you wrote today. Chapter 7 of the book goes further on agility, including the Foundation Reset.", "sents": [[0.03, "Before you go, a quick recap.", 0], [2.39, "The filter gives you a reason for saying yes or no.", 1], [5.85, "Check purpose, mission, and values, then look for the better yes.", 1], [10.47, "Resistance comes in two kinds.", 2], [12.59, "Name your inner critic and answer it once.", 2], [15.47, "Treat an outside “no” as “not yet” and ask a question.", 2], [17.97, "And agility is planned before it's needed.", 3], [19.39, "Find the weak link in a goal now, and decide on a pivot while you're calm.", 3], [26.67, "Select Download my answers for a Word document of what you wrote today.", 4], [30.55, "Chapter 7 of the book goes further on agility, including the Foundation Reset.", 4]], "v": "k1", "cues": [0.03, 2.39, 10.47, 17.97, 26.67]}, "n_4_21": {"dur": 16.48, "text": "That's Lesson 4 done. Four down, and your M.V.P. is starting to do real work. This week, run your core rep: use the filter on one real request, then ask one person for feedback on how you applied it. Next time, you'll build your 90-day plan.", "sents": [[0.05, "That's Lesson 4 done.", 0], [1.93, "Four down, and your M.V.P. is starting to do real work.", 0], [6.13, "This week, run your core rep: use the filter on one real request, then ask one person for feedback on how you applied it.", 1], [13.91, "Next time, you'll build your 90-day plan.", 1]], "v": "k1", "cues": [0.05, 6.13]}, "n_4_3": {"dur": 7.6, "text": "Here's a quick look back at Lesson 3. How do you use your purpose statement in day-to-day decisions? This one isn't scored.", "sents": [[0.03, "Here's a quick look back at Lesson 3.", 0], [2.45, "How do you use your purpose statement in day-to-day decisions?", 0], [6.05, "This one isn't scored.", 1]], "v": "k1", "cues": [0.03, 6.05]}, "n_4_4": {"dur": 25.12, "text": "You'll answer real requests with a better yes or a clear no, using the purpose and mission you wrote. You'll run a decision through a four-question filter. You'll name the sentence your inner critic repeats, and answer it from your purpose. You'll turn one external “no” into a question that makes your idea stronger. Then you'll take one goal you're working toward, find its weak point, and plan the pivot while you're calm.", "sents": [[0.01, "You'll answer real requests with a better yes or a clear no, using the purpose and mission you wrote.", 0], [6.67, "You'll run a decision through a four-question filter.", 1], [9.71, "You'll name the sentence your inner critic repeats, and answer it from your purpose.", 2], [14.35, "You'll turn one external “no” into a question that makes your idea stronger.", 3], [19.27, "Then you'll take one goal you're working toward, find its weak point, and plan the pivot while you're calm.", 4]], "v": "k1", "cues": [0.01, 6.67, 9.71, 14.35, 19.27]}, "n_4_7": {"dur": 34.64, "text": "Here's the filter from the video, presented as four questions. Ask them in order and stop at the first no. First, does it fit your purpose? If it doesn't, it's a distraction, however good it looks. Second, does it move your mission forward: the action, audience, focus, and result you wrote last lesson? Third, does it honor your values? One broken value outweighs nine good reasons. Fourth, at the first no, look for a better yes. Ask who else could grow if you say no, and what you could offer instead.", "sents": [[0.01, "Here's the filter from the video, presented as four questions.", 0], [3.89, "Ask them in order and stop at the first no.", 0], [7.43, "First, does it fit your purpose?", 1], [10.09, "If it doesn't, it's a distraction, however good it looks.", 1], [13.75, "Second, does it move your mission forward: the action, audience, focus, and result you wrote last lesson?", 2], [20.71, "Third, does it honor your values?", 3], [23.37, "One broken value outweighs nine good reasons.", 3], [26.75, "Fourth, at the first no, look for a better yes.", 4], [28.93, "Ask who else could grow if you say no, and what you could offer instead.", 4]], "v": "k1", "cues": [0.01, 7.43, 13.75, 20.71, 26.75]}, "n_4_8": {"dur": 35.44, "text": "Let's look at the shape of Anna's story. Anna's purpose is to champion emerging talent. Her boss offers her a high-profile data project that she'd work on alone, for a full quarter. She runs it through the filter. It doesn't fit her purpose or her mission, so she proposes a better yes: her rising analyst, David, takes the project, and she oversees it. The project gets done, David grows, and her boss sees her thinking strategically. She never actually said no. The filter doesn't make you say no. It gives you a reason you can explain for saying yes or no.", "sents": [[0.01, "Let's look at the shape of Anna's story.", 0], [2.69, "Anna's purpose is to champion emerging talent.", 1], [5.99, "Her boss offers her a high-profile data project that she'd work on alone, for a full quarter.", 1], [11.69, "She runs it through the filter.", 2], [13.51, "It doesn't fit her purpose or her mission, so she proposes a better yes: her rising analyst, David, takes the project, and she oversees it.", 2], [22.67, "The project gets done, David grows, and her boss sees her thinking strategically.", 3], [27.67, "She never actually said no.", 3], [29.85, "The filter doesn't make you say no.", 4], [31.93, "It gives you a reason you can explain for saying yes or no.", 4]], "v": "k1", "cues": [0.01, 2.69, 11.69, 22.67, 29.85]}, "r2_code_pulse": {"dur": 7.36, "text": "Type the code from the last page of the Pulse Check, then select Submit. A quick knowledge check comes next, then your recap.", "sents": [[0.01, "Type the code from the last page of the Pulse Check, then select Submit.", 0], [4.23, "A quick knowledge check comes next, then your recap.", 0]], "v": "r3", "cues": [0.01]}, "r2_form_pulse": {"dur": 8.96, "text": "Answer the five questions, then select Submit. Your code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0, "Answer the five questions, then select Submit.", 0], [3.25, "Your code appears on the last page.", 0], [5.45, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0]}, "r2_pulse": {"dur": 21.36, "text": "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season. It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks. It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing. Select Next, and it opens right here.", "sents": [[0.01, "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season.", 0], [6.57, "It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks.", 1], [12.25, "It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing.", 2], [18.83, "Select Next, and it opens right here.", 2]], "v": "k1", "cues": [0.01, 6.57, 12.25]}};
